<?php
require_once __DIR__.'/../../config/config.php';require_role('teacher');require_once __DIR__.'/../../includes/clinic_availability.php';
$db=getDB();$u=current_user();$students=get_adviser_students($db,$u['id']);$clinic=clinic_availability($db);
$stmt=$db->prepare("SELECT id,employee_id,department FROM teachers WHERE user_id=? LIMIT 1");$stmt->execute([$u['id']]);$teacher=$stmt->fetch()?:[];
$ticket=null;if(!empty($teacher['id'])){$stmt=$db->prepare("SELECT id,queue_number,status,created_at,served_at,completed_at FROM queue_numbers WHERE teacher_id=? AND created_at>=CURDATE() AND status IN ('waiting','called','serving','completed') ORDER BY id DESC LIMIT 1");$stmt->execute([$teacher['id']]);$ticket=$stmt->fetch()?:null;}
$stmt=$db->query("SELECT id,title,created_at FROM announcements WHERE audience='all' ORDER BY is_pinned DESC,created_at DESC LIMIT 3");$announcements=$stmt->fetchAll(PDO::FETCH_ASSOC);
$consultationCount=0;if(!empty($teacher['id'])){$stmt=$db->prepare("SELECT COUNT(*) FROM consultations WHERE teacher_id=? AND patient_type='teacher'");$stmt->execute([$teacher['id']]);$consultationCount=(int)$stmt->fetchColumn();}
$pageTitle='Teacher Dashboard';
$teacherName=trim(($u['first_name']??'').' '.($u['last_name']??''));
?>
<!doctype html><html lang="en"><head><?php include __DIR__.'/../../includes/head.php'; ?><style>
.teacher-card{border:1px solid #e3ebe7;border-radius:16px;box-shadow:0 8px 22px rgba(17,66,43,.06);transition:transform .18s ease,box-shadow .18s ease}.teacher-card:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(17,66,43,.1)}.teacher-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:14px;background:#e9f8f0;color:#087443;font-size:1.3rem}.status-track{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.status-step{border-top:4px solid #dfe7e3;padding-top:9px;font-size:.78rem;color:#6c757d}.status-step.active,.status-step.done{border-color:#12905a;color:#087443;font-weight:700}@media(max-width:575px){.status-track{grid-template-columns:1fr 1fr}}
</style></head><body><div class="app-wrapper"><?php include __DIR__.'/../../components/sidebar.php'; ?><main class="main-content"><?php include __DIR__.'/../../components/navbar.php'; ?><div class="content-area page-enter" id="mainContent">
  <?= dbg_welcome_banner(['name' => $teacherName, 'clinic' => $clinic]) ?>
<div class="row g-4 mb-4">
<div class="col-md-6 col-xl-3"><section class="card teacher-card h-100 p-4"><div class="teacher-icon mb-3"><i class="bi bi-people"></i></div><div class="display-6 fw-bold"><?= count($students) ?></div><h3 class="h5">My Students</h3><p class="small text-muted">Students assigned through your current advisory sections.</p><a class="btn btn-outline-success mt-auto" href="students.php">View Students</a></section></div>
