<div class="col-md-6 col-xl-3"><section class="card teacher-card h-100 p-4"><div class="teacher-icon mb-3"><i class="bi bi-file-earmark-medical"></i></div><div class="display-6 fw-bold"><?= $consultationCount ?></div><h3 class="h5">My Health Record</h3><p class="small text-muted">Your private faculty consultation history and authorized clinical summaries.</p><a class="btn btn-outline-success mt-auto" href="consultations.php">View My Record</a></section></div>
<div class="col-md-6 col-xl-3"><section class="card teacher-card h-100 p-4"><div class="teacher-icon mb-3"><i class="bi bi-megaphone"></i></div><h3 class="h5">Clinic Announcements</h3><?php if(!$announcements): ?><p class="small text-muted">No clinic announcements are available.</p><?php else: ?><ul class="list-unstyled small mb-3"><?php foreach($announcements as $a): ?><li class="border-bottom py-2"><a class="text-decoration-none fw-semibold" href="announcements.php?id=<?= (int)$a['id'] ?>"><?= e($a['title']) ?></a><div class="text-muted"><?= e(date('M j, Y',strtotime($a['created_at']))) ?></div></li><?php endforeach; ?></ul><?php endif; ?><a class="btn btn-outline-success mt-auto" href="announcements.php">View Announcements</a></section></div>
</div>
<section class="card teacher-card p-4"><div class="d-flex justify-content-between align-items-start flex-wrap gap-2 mb-3"><div><h3 class="h5 mb-1">My Clinic Status</h3><p class="small text-muted mb-0">Personal faculty queue and consultation progress.</p></div><?php if($ticket): ?><span class="badge bg-success-subtle text-success fs-6"><?= e($ticket['queue_number']) ?></span><?php endif; ?></div>
<?php if(!$ticket): ?><div class="text-center py-4"><i class="bi bi-ticket-perforated fs-1 text-muted"></i><p class="text-muted mt-2 mb-3">You have no clinic queue activity today.</p><a class="btn btn-success" href="queue.php">Join Clinic Queue</a></div><?php else: ?><?php $order=['waiting','called','serving','completed'];$position=array_search($ticket['status'],$order,true); ?><div class="status-track"><?php foreach($order as $i=>$status): ?><div class="status-step <?= $i<$position?'done':($i===$position?'active':'') ?>"><?= e($status==='serving'?'In Consultation':ucfirst($status)) ?></div><?php endforeach; ?></div><p class="small text-muted mt-3 mb-0">Ticket created <?= e(format_datetime($ticket['created_at'])) ?>.</p><?php endif; ?>
</section></div></main></div><?php include __DIR__.'/../../components/footer.php'; ?></body></html>
